parameters.jsCode:
const raw = $input.first().json;

// n8n pasa el error en diferentes rutas dependiendo de la versión
const workflowNombre = raw.workflow?.name || 
                       raw.workflowData?.name || 
                       'Desconocido';

const nodo = raw.execution?.lastNodeExecuted || 
             raw.lastNodeExecuted || 
             'Desconocido';

const mensajeError = raw.error?.message || 
                     raw.error?.description ||
                     raw.message ||
                     raw.description ||
                     JSON.stringify(raw.error) ||
                     'Ver datos de entrada';

const datosEntrada = JSON.stringify({
    workflow: workflowNombre,
    nodo: nodo,
    error: raw.error,
    execution: raw.execution?.id || raw.id
});

return [{
    json: {
        workflow_nombre: workflowNombre,
        nodo: nodo,
        mensaje_error: mensajeError,
        datos_entrada: datosEntrada
    }
}];
